from __future__ import annotations
import argparse
import json
import sys
import urllib.error
import urllib.request


def call(port, method, path, body=None):
    if isinstance(body, (dict, list)):
        data = json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    elif isinstance(body, str):
        data = body.encode("utf-8")
    else:
        data = body
    req = urllib.request.Request(f"http://127.0.0.1:{port}{path}", data=data, method=method)
    if data is not None and method in ("POST", "PUT", "PATCH"):
        req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=5) as response:
            return response.status, dict(response.headers.items()), response.read()
    except urllib.error.HTTPError as exc:
        return exc.code, dict(exc.headers.items()), exc.read()


def parsed(raw):
    return json.loads(raw.decode("utf-8"))


def check(condition, message):
    if not condition:
        raise AssertionError(message)


def expect_error(result, status, code):
    actual, _headers, raw = result
    check(actual == status, f"expected {status}, got {actual}")
    check(parsed(raw).get("error") == code, f"expected {code}, got {parsed(raw)}")


def register(port, rid, keys, advisory, component, severity, summary, fixed=None, include_fixed=False):
    advisory_key, fixed_key = keys
    payload = {advisory_key: advisory, "component": component, "severity": severity, "summary": summary}
    if include_fixed:
        payload[fixed_key] = fixed
    return call(port, "POST", f"/resources/{rid}/vulnerabilities", payload)


def discover_schema(port, rid):
    for keys in (("advisory", "fixed_version"), ("advisory_id", "fix_version")):
        result = register(port, rid, keys, "ADV-1", "openssl", "HIGH", "overflow")
        if result[0] == 201:
            return keys, result
        check(result[0] == 400, "unexpected response while discovering documented field names")
    raise AssertionError("neither documented vulnerability field spelling was accepted")


def check_record(raw, value, keys, expected_advisory, expected_component, expected_severity, expected_summary, expected_fixed):
    advisory_key, fixed_key = keys
    check(raw.endswith(b"\n"), "success JSON must end with a newline")

