def _handle_policies_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    # Validate the whole body before touching any store, so a bad request
    # can never leave a partial policy.
    try:
        build_policy_fields(payload)
    except PolicyValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        record, created = policy_store.add(raw_id, payload)
    except PolicyError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    return _json_response(
        start_response,
        "201 Created" if created else "200 OK",
        record.to_dict(raw_id),
        trailing_newline=True,
    )


def _handle_policies_get(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    record = policy_store.get(raw_id)
    if record is None:
        return _error(
            start_response,
            "404 Not Found",
            "policy_not_found",
            "No admission policy is registered for this resource.",
        )

    return _json_response(
        start_response,
        "200 OK",
        record.to_dict(raw_id),
        trailing_newline=True,
    )


def _handle_policies(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "POST":
        return _handle_policies_post(environ, raw_id, start_response)
    if method == "GET":
        return _handle_policies_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_admission(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # The decision is read-only and takes no request body; any bytes are a
    # bad request rather than being silently ignored.
    if _read_body(environ):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "This endpoint does not accept a request body.",
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    policy = policy_store.get(raw_id)
    if policy is None:
        return _error(
            start_response,
            "404 Not Found",
            "policy_not_found",
            "No admission policy is registered for this resource.",
        )

    license_record = sbom_store.get_license(raw_id)
    severities = [
        record.severity
        for record in vulnerability_store.list_for(raw_id)
    ]
    reasons = evaluate_admission(
        policy,
        state=lifecycle_store.get(raw_id).state,
        has_sbom=sbom_store.get_sbom(raw_id) is not None,
        has_license=license_record is not None,
        spdx_id=license_record.spdx_id if license_record is not None else None,
        has_provenance=provenance_store.get(raw_id) is not None,
        severities=severities,
    )
    return _json_response(
        start_response,
        "200 OK",
        {"id": raw_id, "allowed": not reasons, "reasons": reasons},
        trailing_newline=True,
    )


