def _admission_body_error(environ: dict[str, Any]) -> str | None:
    """Reject an admission POST that declares or carries a request body.

    A missing ``Content-Length`` is the normal, body-less case. An explicit
    length of zero is accepted; any other (non-integer or positive) value
    means the request carries a body and is rejected.
    """

    raw_length = environ.get("CONTENT_LENGTH")
    if raw_length is None:
        return None
    if (
        not isinstance(raw_length, str)
        or _NON_NEGATIVE_INT_PATTERN.fullmatch(raw_length) is None
        or int(raw_length) > 0
    ):
        return "This endpoint does not accept a request body."
    return None


